#include <stdio.h>
#include <stdlib.h>

int adj[8][8];
int color[8];
char found_cycle = 0;

void dfs(int node) {
    if (found_cycle) return;
    color[node] = 1;
    for (int i = 0; i < 8; i++) {
        if (adj[node][i] && color[i] == 0) {
            dfs(i);
        } else if (adj[node][i] && color[i] == 1) {
            found_cycle = 1;
            return;
        }
    }
    color[node] = 2;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("INVALID_INPUT\n");
        return 1;
    }
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            adj[i][j] = 0;
        }
    }
    for (int i = 1; i < argc; i += 2) {
        int u = atoi(argv[i]);
        int v = atoi(argv[i + 1]);
        adj[u][v] = 1;
        adj[v][u] = 1;
    }
    for (int i = 0; i < 8; i++) {
        color[i] = 0;
    }
    for (int i = 0; i < 8; i++) {
        if (color[i] == 0) dfs(i);
    }
    if (found_cycle) {
        printf("CYCLE\n");
    } else {
        printf("ACYCLIC\n");
    }
    return 0;
}
